// region-set booking facts via its own lemmas.
#[verus_spec(result =>
    requires
        region.inv(),
    ensures
        match result {
            Ok(()) => true,
            Err(_) => true,
        },
)]
pub(super) fn alloc_range(region: &TruncatedMemoryRegion<PhysicalAddress>) -> Result<(), Error> {
    instance().alloc_range(region)
}

